    job_estimation: function(frm) {
        console.log('Job Estimation changed:', frm.doc.job_estimation);
        
        if (frm.doc.job_estimation) {
            // Clear existing rows in raw_material_availabilty
            frm.clear_table('raw_material_availabilty');
            
            // Call server method to get BOM items
            frappe.call({
                method: 'frappe.client.get_list',
                args: {
                    doctype: 'Materials Required_BOQ',
                    filters: {
                        parent: frm.doc.job_estimation
                    },
                    fields: ['name', 'bom']
                },
                callback: function(r) {
                    console.log('BOQ Response:', r.message);
                    if (r.message && r.message.length > 0) {
                        // Process each BOQ item
                        r.message.forEach(function(boq_item) {
                            console.log('Processing BOQ item:', boq_item);
                            if (boq_item.bom) {
                                // Get BOM items for each BOM
                                get_bom_items(frm, boq_item.bom);
                            }
                        });
                    } else {
                        console.log('No BOQ items found for this job estimation');
                        frappe.msgprint('No BOQ items found for this job estimation');
                    }
                }
            });
        }
    }
});

// Function to get BOM items and populate child table
function get_bom_items(frm, bom_name) {
    console.log('Getting BOM items for:', bom_name);
    
    frappe.call({
        method: 'frappe.client.get_list',
        args: {
            doctype: 'BOM Item', // Correct DocType name
            filters: {
                parent: bom_name
            },
            fields: ['item_name', 'qty']
        },
        callback: function(r) {
            console.log('BOM Items Response:', r.message);
            if (r.message && r.message.length > 0) {
                r.message.forEach(function(item) {
                    console.log('Adding item:', item);
                    // Add row to raw_material_availabilty child table
                    let row = frm.add_child('raw_material_availabilty');
                    row.item_name = item.item_name;
                    row.qty = item.qty;
                });
                
                // Refresh the child table
                frm.refresh_field('raw_material_availabilty');
                frappe.msgprint('Materials populated successfully!');
            } else {
                console.log('No BOM items found for BOM:', bom_name);
                frappe.msgprint('No BOM items found for BOM: ' + bom_name);
            }
        }
    });
}

